        var actor=Actor(owner);if(actor==null)return;var before=owner.Get("_editing").AsBool()?Before(owner):_timeline.animation_snapshot(actor);var after=before.Duplicate();after.Clear();Resource? primary=null;foreach(var value in before)foreach(var item in value.As<Resource>().Get("keys").AsGodotArray()){var key=item.As<Resource>();if(key.Get("id").AsString()==primaryId)primary=key;}if(primary==null)return;var ids=Selected(owner).Duplicate();if(!ids.Contains(primaryId)){ids.Clear();ids.Add(primaryId);}Resource? document=null;bool loaded=false;
