h.Abs(keys[i].As<Resource>().Get("time").AsDouble()-keys[i-1].As<Resource>().Get("time").AsDouble())<.00001)return;after.Add(copy);}if(preview)_timeline.restore_animation(Model(owner),actor,after);else _timeline.commit_animation_edit(Model(owner),actor,before,after,"Change Selected Keyframes");
    }
    public void begin_edit(Control owner){var actor=Actor(owner);if(actor==null)return;owner.Set("_editing",true);owner.Set("_before",_timeline.animation_snapshot(actor));}
